CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE installation (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), setup_token_hash text, owner_id uuid, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO installation(singleton) VALUES(true);
CREATE TABLE users(id uuid PRIMARY KEY, email text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE installation ADD FOREIGN KEY(owner_id) REFERENCES users(id);
CREATE TABLE authorization_epochs(owner_id uuid PRIMARY KEY REFERENCES users(id), revision bigint NOT NULL DEFAULT 1);
CREATE TABLE principals(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), principal_type text NOT NULL, auth_method text NOT NULL, trust_level text NOT NULL, source text NOT NULL, UNIQUE(owner_id,id));
CREATE TABLE sessions(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), principal_id uuid NOT NULL, token_hash text NOT NULL UNIQUE, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(owner_id,principal_id) REFERENCES principals(owner_id,id));
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE login_attempts(key_hash text PRIMARY KEY, attempts integer NOT NULL, window_start timestamptz NOT NULL);
CREATE TABLE settings(owner_id uuid PRIMARY KEY REFERENCES users(id), value jsonb NOT NULL DEFAULT '{"installation_mode":"LOCAL_ONLY","autonomy_mode":"OBSERVE","allow_private_cloud":false}', revision bigint NOT NULL DEFAULT 1);
CREATE TABLE events(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), event_type text NOT NULL, source text NOT NULL, principal_id uuid NOT NULL, timestamp timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL, trust_level text NOT NULL, privacy_class text NOT NULL, correlation_id uuid NOT NULL, related_entities jsonb NOT NULL DEFAULT '[]', source_event_key text NOT NULL, classification jsonb, UNIQUE(owner_id,id), UNIQUE(owner_id,source,source_event_key), FOREIGN KEY(owner_id,principal_id) REFERENCES principals(owner_id,id));
CREATE INDEX events_owner_time ON events(owner_id,timestamp,id);
CREATE INDEX events_correlation ON events(owner_id,correlation_id);
CREATE TABLE event_deliveries(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), event_id uuid NOT NULL, consumer text NOT NULL, state text NOT NULL DEFAULT 'PENDING', lease_until timestamptz, fence bigint NOT NULL DEFAULT 0, attempts integer NOT NULL DEFAULT 0, UNIQUE(owner_id,consumer,event_id), FOREIGN KEY(owner_id,event_id) REFERENCES events(owner_id,id));
CREATE INDEX event_delivery_lease ON event_deliveries(state,lease_until);
CREATE TABLE tasks(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), event_id uuid, principal_id uuid NOT NULL, correlation_id uuid NOT NULL, title text NOT NULL, state text NOT NULL DEFAULT 'QUEUED' CHECK(state IN ('QUEUED','RUNNING','WAITING_FOR_APPROVAL','WAITING_FOR_RESOURCE','COMPLETED','FAILED','CANCELLED','TIMED_OUT')), revision bigint NOT NULL DEFAULT 1, fence bigint NOT NULL DEFAULT 0, lease_holder uuid, lease_until timestamptz, checkpoint jsonb NOT NULL DEFAULT '{"phase":"NOTIFICATION"}', wait_reason text, evidence jsonb NOT NULL DEFAULT '[]', unresolved_call_ids jsonb NOT NULL DEFAULT '[]', consumer text NOT NULL DEFAULT 'foundation', retry_of uuid, expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(owner_id,consumer,event_id), FOREIGN KEY(owner_id,event_id) REFERENCES events(owner_id,id), FOREIGN KEY(owner_id,principal_id) REFERENCES principals(owner_id,id), FOREIGN KEY(owner_id,retry_of) REFERENCES tasks(owner_id,id));
CREATE INDEX tasks_claim ON tasks(state,lease_until,expires_at);
CREATE INDEX tasks_owner ON tasks(owner_id,created_at,id);
CREATE INDEX tasks_correlation ON tasks(owner_id,correlation_id);
CREATE TABLE task_steps(id uuid PRIMARY KEY, owner_id uuid NOT NULL, task_id uuid NOT NULL, name text NOT NULL, state text NOT NULL, fence bigint NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,task_id,name), FOREIGN KEY(owner_id,task_id) REFERENCES tasks(owner_id,id));
CREATE TABLE audit_events(sequence bigserial PRIMARY KEY, id uuid NOT NULL UNIQUE, owner_id uuid NOT NULL REFERENCES users(id), correlation_id uuid NOT NULL, principal_id uuid NOT NULL, event_id uuid, task_id uuid, operation text NOT NULL, reason text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', timestamp timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(owner_id,principal_id) REFERENCES principals(owner_id,id), FOREIGN KEY(owner_id,event_id) REFERENCES events(owner_id,id), FOREIGN KEY(owner_id,task_id) REFERENCES tasks(owner_id,id));
CREATE INDEX audit_owner_correlation ON audit_events(owner_id,correlation_id,sequence);
CREATE FUNCTION reject_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit is append only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON audit_events FOR EACH STATEMENT EXECUTE FUNCTION reject_audit_mutation();
REVOKE UPDATE, DELETE, TRUNCATE ON audit_events FROM PUBLIC;
CREATE TABLE notifications(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), task_id uuid, correlation_id uuid NOT NULL, severity text NOT NULL CHECK(severity IN ('INFO','ACTION_REQUIRED','IMPORTANT','URGENT')), title text NOT NULL, body text NOT NULL, privacy_class text NOT NULL DEFAULT 'PRIVATE', trust_level text NOT NULL DEFAULT 'UNTRUSTED_EXTERNAL', read_at timestamptz, acknowledged_at timestamptz, dismissed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,id), UNIQUE(owner_id,task_id), FOREIGN KEY(owner_id,task_id) REFERENCES tasks(owner_id,id));
CREATE INDEX notifications_owner_time ON notifications(owner_id,created_at,id);
CREATE FUNCTION legal_task_transition() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.state<>NEW.state AND NOT ((OLD.state='QUEUED' AND NEW.state IN ('RUNNING','CANCELLED','TIMED_OUT','FAILED')) OR (OLD.state='RUNNING' AND NEW.state IN ('WAITING_FOR_APPROVAL','WAITING_FOR_RESOURCE','COMPLETED','FAILED','CANCELLED','TIMED_OUT')) OR (OLD.state IN ('WAITING_FOR_APPROVAL','WAITING_FOR_RESOURCE') AND NEW.state IN ('QUEUED','CANCELLED','TIMED_OUT','FAILED'))) THEN RAISE EXCEPTION 'illegal task transition'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER task_transition BEFORE UPDATE ON tasks FOR EACH ROW EXECUTE FUNCTION legal_task_transition();
ALTER TABLE principals ADD CHECK(principal_type IN ('WEB_USER','MOBILE_USER','COMPUTER_NODE','EMAIL_SENDER','AUTOMATION','WEBHOOK','AGENT','SYSTEM','MCP_SERVER')), ADD CHECK(trust_level IN ('OWNER_AUTHENTICATED','SYSTEM','UNTRUSTED_EXTERNAL'));
ALTER TABLE events ADD CHECK(event_type IN ('EMAIL_RECEIVED','EMAIL_REPLIED','CALENDAR_CHANGED','FILE_CREATED','FILE_MODIFIED','FILE_DELETED','FILE_SHARED','COMPUTER_CONNECTED','COMPUTER_DISCONNECTED','DEVICE_EVENT','SCHEDULE_TRIGGER','TIMER_TRIGGER','WEBHOOK_RECEIVED','GITHUB_EVENT','HOME_EVENT','TASK_COMPLETED','TASK_FAILED','USER_MESSAGE','APPROVAL_ACCEPTED','APPROVAL_DENIED')), ADD CHECK(privacy_class IN ('PUBLIC','PERSONAL','PRIVATE','HIGHLY_PRIVATE','SECRET')), ADD CHECK(trust_level IN ('OWNER_AUTHENTICATED','SYSTEM','UNTRUSTED_EXTERNAL'));
ALTER TABLE event_deliveries ADD CHECK(state IN ('PENDING','CLAIMED','ACKNOWLEDGED'));
